@code {
    private AppointmentModel Model { get; set; } = new();
    private EditContext? editContext;
    private ValidationMessageStore? messageStore;

    private List<string> Doctors { get; set; } = [];
    private List<string> TimeSlots { get; set; } = [];

    private bool ShowStep2 { get; set; }
    private bool IsChecking { get; set; }
    private bool AvailabilityConfirmed { get; set; }
    private bool IsBooked { get; set; }

    protected override async Task OnInitializedAsync()
    {
        editContext = new EditContext(Model);
        messageStore = new ValidationMessageStore(editContext);
        editContext.OnFieldChanged += (_, args) =>
        {
            // Clear server errors when the user edits a field
            messageStore?.Clear(args.FieldIdentifier);
            AvailabilityConfirmed = false;
        };

        Doctors = await AppointmentSvc.GetDoctorsAsync();
    }

    private void ProceedToStep2()
    {
        messageStore?.Clear();

        // Validate only step-1 fields
        var step1Valid = true;
        var step1Fields = new[] {
            nameof(AppointmentModel.PatientName),
            nameof(AppointmentModel.Email),
            nameof(AppointmentModel.Phone),
            nameof(AppointmentModel.InsuranceProvider)
        };

        // Trigger validation so DataAnnotations run
        editContext!.Validate();

        foreach (var field in step1Fields)
        {
            var fi = editContext.GetFieldIdentifier(field);
            if (editContext.GetValidationMessages(fi).Any())
            {
                step1Valid = false;
            }
        }

        if (step1Valid)
        {
            ShowStep2 = true;
        }
    }

    private void BackToStep1()
    {
        ShowStep2 = false;
        AvailabilityConfirmed = false;
    }

    private async Task OnDateChanged()
    {
        AvailabilityConfirmed = false;
        if (!string.IsNullOrEmpty(Model.Doctor) && Model.AppointmentDate.HasValue)
        {
            TimeSlots = await AppointmentSvc.GetAvailableTimeSlotsAsync(
                Model.Doctor, Model.AppointmentDate.Value);
            Model.TimeSlot = null;
        }
    }

    private async Task CheckAvailability()
    {
        messageStore?.Clear();
        editContext!.Validate();

        // Check step-2 client validations first
        if (!IsStep2Valid())
            return;

        // Future-date check
        if (Model.AppointmentDate!.Value <= DateOnly.FromDateTime(DateTime.Today))
            return;

        IsChecking = true;
        try
        {
            var errors = await AppointmentSvc.ValidatePatientAsync(
                Model.Email!, Model.InsuranceProvider!, Model.Doctor!, Model.TimeSlot);

            if (errors.Count > 0)
            {
                foreach (var (field, message) in errors)
                {
                    var fi = editContext.GetFieldIdentifier(field);
                    messageStore!.Add(fi, message);
                }
                editContext.NotifyValidationStateChanged();
                AvailabilityConfirmed = false;
            }
            else
            {
                AvailabilityConfirmed = true;
            }
        }
        finally
        {
            IsChecking = false;
        }
    }

    private bool IsStep2Valid()
    {
        var step2Fields = new[] {
            nameof(AppointmentModel.Doctor),
            nameof(AppointmentModel.AppointmentDate),
            nameof(AppointmentModel.TimeSlot),
            nameof(AppointmentModel.ReasonForVisit)
        };

        foreach (var field in step2Fields)
        {
            var fi = editContext!.GetFieldIdentifier(field);
            if (editContext.GetValidationMessages(fi).Any())
                return false;
        }
        return true;
    }

    private void HandleSubmit()
    {
        if (AvailabilityConfirmed)
        {
            IsBooked = true;
        }
    }
}

